// WF12 Market Intelligence Report Builder config — DETERMINISTIC v0.1 skeleton (DEC-112/118).
// $0 by default: no Claude, no Telegram send, no external API. Reads WF10 output tabs, writes ONE
// market_intelligence_reports row (schema: docs/MARKET_INTELLIGENCE_REPORT_SCHEMA.md) + ONE agent_requests row.
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
function moscowStamp(){var z=function(n){return String(n).padStart(2,'0');};var m=new Date(Date.now()+10800000);return m.getUTCFullYear()+z(m.getUTCMonth()+1)+z(m.getUTCDate())+'_'+z(m.getUTCHours())+z(m.getUTCMinutes())+z(m.getUTCSeconds());}
const stamp=moscowStamp();
return [{ json: {
  // --- hard-off defaults (DEC-112): the deterministic report is complete without any of these.
  enable_llm_summary:false,          // optional Claude summary — NOT implemented; guard node throws if true
  telegram_send:false,               // Telegram delivery — NOT implemented in v0.1 (delivered_to stays 'none')
  report_type:'on_demand',           // on_demand / weekly_digest / no_data_notice (auto-set on no_data)
  niche_id:'credit_brokerage',
  region:'Москва/МО',
  top_n:3,
  requested_by:'operator',
  report_id:'report_'+stamp,
  run_id:'wf12_'+stamp,
  agent_request_id:'wf12_req_'+stamp,
  created_at:moscowIsoNow()
}}];

// Deterministic Report Builder core (DEC-112/118): latest WF10 snapshot -> 20-col report row + Markdown.
// Facts only — every number/name comes from the WF10 tabs; nothing is invented; no contacts are surfaced.
function str(v){return v==null?'':String(v).trim();}
function num(v){var n=Number(v);return isFinite(n)?n:0;}
function rowsOf(name){try{return $(name).all().map(i=>i.json).filter(r=>r&&Object.keys(r).length);}catch(e){return [];}}
const cfg=$('Set Report Config').first().json;
const topN=Number(cfg.top_n)||3;
const profiles=rowsOf('Read competitor_profiles');
const angles=rowsOf('Read market_angles');
const signals=rowsOf('Read audience_activity_signals');
const plans=rowsOf('Read content_positioning_plan').filter(p=>str(p.plan_id));
// --- run selection: plan_id carries the WF10 run stamp (plan_<stamp> or plan_<stamp>_no_data; one plan per run)
function planStamp(p){return str(p.plan_id).replace(/^plan_/,'').replace(/_no_data$/,'');}
plans.sort((a,b)=>planStamp(a)<planStamp(b)?-1:1);
if(!plans.length){throw new Error('WF12: content_positioning_plan is empty — run WF10 at least once before building a report.');}
const latest=plans[plans.length-1];
const stamp=planStamp(latest);
const prev=plans.filter(p=>planStamp(p)!==stamp).pop()||null;
const prevStamp=prev?planStamp(prev):'';
const isNoData=/_no_data$/.test(str(latest.plan_id))||/rows=0/.test(str(latest.source_evidence));
const rowsAfter=(function(){const m=str(latest.source_evidence).match(/rows=(\d+)/);return m?Number(m[1]):(isNoData?0:0);})();
// --- snapshot filters: WF10 ids/notes carry the run stamp
const profNow=profiles.filter(p=>str(p.notes).indexOf('wf10_'+stamp)>=0||str(p.notes).indexOf(stamp)>=0);
const angNow=angles.filter(a=>str(a.angle_id).endsWith(stamp));
const angPrev=prevStamp?angles.filter(a=>str(a.angle_id).endsWith(prevStamp)):[];
const sigNow=signals.filter(s=>str(s.signal_id).endsWith(stamp));
// --- deterministic top lists
const topComp=profNow.slice().sort((a,b)=>(num(b.evidence_count)-num(a.evidence_count))||(num(b.source_confidence_score)-num(a.source_confidence_score))).slice(0,topN)
  .map(p=>str(p.competitor_name)+' (evidence '+num(p.evidence_count)+', conf '+num(p.source_confidence_score)+')');
function angleKey(a){return str(a.angle_id).replace(/^angle_/,'').replace(/_\d{8}_\d{6}$/,'');} // strip the trailing run stamp -> stable angle key across runs
const prevFreq={};for(const a of angPrev){prevFreq[angleKey(a)]=num(a.frequency);}
const topAng=angNow.slice().sort((a,b)=>num(b.frequency)-num(a.frequency)).slice(0,topN)
  .map(a=>{const k=angleKey(a);const f=num(a.frequency);let trend='·';
    if(prevStamp){const pf=prevFreq[k];trend=(pf===undefined)?'NEW':(f>pf?'↑':(f<pf?'↓':'='));}
    return str(a.angle_text)+' (x'+f+(prevStamp?(' '+trend):'')+')';});
const audSummary=sigNow.map(s=>str(s.platform)+': questions='+num(s.question_count)+', objections='+num(s.objection_count)+', complaints='+num(s.complaint_count)+', buying_intent='+num(s.buying_intent_count)+(str(s.top_pains)?(', pains: '+str(s.top_pains)):'')).join(' | ');
// --- mandatory source-mix label (DEC-108): never imply all data was collected live in this run
const SOURCE_MIX='mixed: live + historical/manual + web pipeline';
const reportType=isNoData?'no_data_notice':str(cfg.report_type);
const NO_DATA_TEXT='no_data; broaden filters or source scope';
// --- deterministic Markdown render (the full report; v0.1 keeps it inline in result/notes, no file write)
const md=[
'# Market intelligence report '+str(cfg.report_id),
'',
'- niche: '+str(cfg.niche_id)+' · region: '+str(cfg.region)+' · WF10 run: wf10_'+stamp+(prevStamp?(' · prev: wf10_'+prevStamp):' · prev: (none — first report, no trends)'),
'- **Источники: '+SOURCE_MIX+'** · rows_after_filters='+rowsAfter,
'',
isNoData?('**NO DATA:** '+NO_DATA_TEXT):[
'## Топ конкурентов',topComp.length?topComp.map((c,i)=>(i+1)+'. '+c).join('\n'):'(none in snapshot)',
'','## Топ углов',topAng.length?topAng.map((a,i)=>(i+1)+'. '+a).join('\n'):'(none in snapshot)',
'','## Активность аудитории (aggregate-only)',audSummary||'(no signals in snapshot)',
'','## План контента','plan: '+str(latest.plan_id)+' — '+str(latest.top_angles)
].join('\n'),
'',
'_Deterministic report (DEC-112): no LLM, no contacts, no outreach. $0._'
].join('\n');
// --- 20-column market_intelligence_reports row (docs/MARKET_INTELLIGENCE_REPORT_SCHEMA.md)
return [{ json: {
  report_id:str(cfg.report_id),
  created_at:str(cfg.created_at),
  report_type:reportType,
  niche_id:str(cfg.niche_id),
  region:str(cfg.region),
  time_window_days:30,
  wf10_run_id:'wf10_'+stamp,
  prev_wf10_run_id:prevStamp?('wf10_'+prevStamp):'',
  source_mix:SOURCE_MIX,
  rows_after_filters:rowsAfter,
  top_competitors:isNoData?'':topComp.join(' | '),
  top_angles:isNoData?'':topAng.join(' | '),
  audience_summary:isNoData?'':audSummary,
  content_plan_ref:str(latest.plan_id),
  report_markdown_path:'',
  llm_summary:'',
  llm_recommendations:'',
  llm_cost_usd:0,
  delivered_to:'none',
  notes:(isNoData?('no_data_notice; recommendation: '+NO_DATA_TEXT+'; '):'')+'wf12 v0.1 deterministic skeleton (DEC-118); llm disabled (DEC-112); markdown inline below || '+md
}}];

// LLM SUMMARY GUARD — the optional Claude branch is NOT implemented in the WF12 v0.1 skeleton (DEC-112/118).
// This workflow contains NO HTTP node. Enabling enable_llm_summary requires, in order: explicit operator
// approval, a bounded facts-only prompt (WF10 table rows + run stats ONLY — never raw contact fields),
// a token cap, and cost recording in agent_requests + COSTS_AND_LIMITS.md.
// Claude summarizes deterministic facts only: no invented facts/competitors/trends, no contacts, no outreach.
throw new Error('WF12 enable_llm_summary is not implemented in the v0.1 skeleton. Deterministic report only (enable_llm_summary=false). The optional Claude summary requires explicit operator approval + bounded prompt + cost recording (see docs/REPORTING_AND_TELEGRAM_SUMMARY_PLAN.md §3).');

// Final run summary. No external calls.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Report Config').first().json;
const rep=$('Build Deterministic Report').first().json;
return [{ json: {
  workflow:'12 - Market Intelligence Report Builder (deterministic skeleton)',
  report_id:str(rep.report_id),
  report_type:str(rep.report_type),
  wf10_run_id:str(rep.wf10_run_id),
  prev_wf10_run_id:str(rep.prev_wf10_run_id)||'(none)',
  rows_after_filters:rep.rows_after_filters,
  top_competitors:str(rep.top_competitors),
  top_angles:str(rep.top_angles),
  source_mix:str(rep.source_mix),
  enable_llm_summary:false,
  llm_cost_usd:0,
  telegram_send:false,
  delivered_to:'none',
  next_action:(str(rep.report_type)==='no_data_notice')?'no_data report written; broaden filters/source scope before the next WF10 run.':'Inspect market_intelligence_reports + agent_requests rows. Trends need >=2 WF10 runs. Claude summary / Telegram delivery = separate gated steps.'
}}];
